Here’s the **zero-credit version**—no Magic Hour calls or credits used.

Save the code below as **`focus-carousel.html`**, open it in your browser, and click each slide’s **Download PNG** button. It exports five **1080 × 1350 px (4:5)** images, ready for Instagram, with no cover or closing slide.

```html
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Focus carousel</title>
<style>
  * { box-sizing: border-box; }
  body {
    margin: 0;
    padding: 32px 20px;
    background: #eaf1f8;
    color: #123b75;
    font-family: Arial, sans-serif;
  }
  main {
    max-width: 1150px;
    margin: auto;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 24px;
  }
  article {
    padding: 12px;
    background: white;
    border-radius: 16px;
    box-shadow: 0 6px 24px #123b7510;
  }
  article svg {
    display: block;
    width: 100%;
    height: auto;
    border-radius: 8px;
  }
  button {
    display: block;
    width: 100%;
    margin-top: 12px;
    padding: 13px;
    border: 0;
    border-radius: 8px;
    background: #165dce;
    color: white;
    font: bold 14px Arial, sans-serif;
    cursor: pointer;
  }
  button:hover { background: #104ba9; }
</style>
</head>
<body>
<main id="slides"></main>
<script>
const slides = [
  {
    lines: ["Clear your", "desk"],
    icon: `
      <rect x="30" y="115" width="260" height="18" rx="9"/>
      <path d="M60 133v92M260 133v92"/>
      <rect x="95" y="28" width="130" height="70" rx="8"/>
      <path d="M160 98v17M135 115h50"/>
      <path d="M245 115V73h35v42M255 73V48M270 73V40"/>
    `
  },
  {
    lines: ["Silence", "notifications"],
    icon: `
      <path d="M83 170h154l-20-30V99
               c0-33-24-58-57-58s-57 25-57 58v41z"/>
      <path d="M138 197c5 24 39 24 44 0"/>
      <path d="M160 22v19M55 38l210 190"/>
      <path d="M240 60c14 13 21 30 21 49"/>
    `
  },
  {
    lines: ["Pick one", "task"],
    icon: `
      <rect x="65" y="28" width="190" height="204" rx="15"/>
      <rect x="119" y="17" width="82" height="30" rx="8"
            fill="#eaf3ff"/>
      <rect x="94" y="84" width="38" height="38" rx="7"
            fill="#165dce" stroke="#165dce"/>
      <path d="M102 102l9 9 14-17" stroke="white"/>
      <path d="M153 103h70M94 155h129M94 192h89"/>
    `
  },
  {
    lines: ["Set a", "timer"],
    icon: `
      <circle cx="160" cy="140" r="88"/>
      <rect x="135" y="14" width="50" height="21" rx="6"/>
      <path d="M160 35v17M222 68l19-19M231 39l20 20"/>
      <path d="M160 76v13M224 140h-13M160 204v-13
               M96 140h13"/>
      <path d="M160 140V99M160 140l35 24"/>
      <circle cx="160" cy="140" r="7" fill="#165dce"
              stroke="none"/>
    `
  },
  {
    lines: ["Take a", "short break"],
    icon: `
      <path d="M77 100h148v58c0 39-30 65-74 65
               s-74-26-74-65z"/>
      <path d="M225 110h15c48 0 48 65 0 65h-18"/>
      <path d="M64 238h185"/>
      <path d="M115 76c-23-22 18-27 0-51
               M154 76c-23-22 18-27 0-51
               M193 76c-23-22 18-27 0-51"/>
    `
  }
];

function makeSVG(slide, index) {
  return `<svg xmlns="http://www.w3.org/2000/svg"
    width="1080" height="1350" viewBox="0 0 1080 1350"
    role="img" aria-label="${index + 1}. ${slide.lines.join(" ")}">
    <rect width="1080" height="1350" fill="#ffffff"/>

    <rect x="80" y="80" width="920" height="1190" rx="36"
          fill="none" stroke="#e4effc" stroke-width="3"/>

    <circle cx="155" cy="155" r="43" fill="#165dce"/>
    <text x="155" y="171" text-anchor="middle"
          font-family="Arial, Helvetica, sans-serif"
          font-size="46" font-weight="700" fill="#ffffff">
      ${index + 1}
    </text>

    <circle cx="540" cy="472" r="182" fill="#eaf3ff"/>
    <g transform="translate(380 347)"
       fill="none" stroke="#165dce" stroke-width="10"
       stroke-linecap="round" stroke-linejoin="round">
      ${slide.icon}
    </g>

    <g text-anchor="middle" fill="#123b75"
       font-family="Arial, Helvetica, sans-serif"
       font-size="88" font-weight="700" letter-spacing="-2">
      <text x="540" y="822">${slide.lines[0]}</text>
      <text x="540" y="928">${slide.lines[1]}</text>
    </g>

    <rect x="498" y="1020" width="84" height="8" rx="4"
          fill="#165dce"/>
  </svg>`;
}

async function downloadPNG(svg, index, button) {
  button.disabled = true;
  button.textContent = "Preparing…";
  const url = URL.createObjectURL(
    new Blob([svg], { type: "image/svg+xml;charset=utf-8" })
  );

  try {
    const image = new Image();
    await new Promise((resolve, reject) => {
      image.onload = resolve;
      image.onerror = reject;
      image.src = url;
    });

    const canvas = document.createElement("canvas");
    canvas.width = 1080;
    canvas.height = 1350;
    canvas.getContext("2d").drawImage(image, 0, 0);

    const blob = await new Promise(resolve =>
      canvas.toBlob(resolve, "image/png")
    );
    if (!blob) throw new Error("PNG export failed");

    const pngURL = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = pngURL;
    link.download = `focus-tip-${index + 1}.png`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(pngURL), 10000);
  } catch (error) {
    alert("Export failed. Please try opening this file in Chrome or Firefox.");
  } finally {
    URL.revokeObjectURL(url);
    button.disabled = false;
    button.textContent = `Download PNG — slide ${index + 1}`;
  }
}

slides.forEach((slide, index) => {
  const svg = makeSVG(slide, index);
  const article = document.createElement("article");
  article.innerHTML = svg;

  const button = document.createElement("button");
  button.textContent = `Download PNG — slide ${index + 1}`;
  button.onclick = () => downloadPNG(svg, index, button);

  article.appendChild(button);
  document.getElementById("slides").appendChild(article);
});
</script>
</body>
</html>
```

